// apps/backend/src/routes/admin.partnerLinks.test.ts
//
// Ops management of partner links: HOUSE ADMIN / SUPERADMIN only; the code is
// generated by the server (a body code is ignored); the customerId comes from
// the workspace; deactivate (never delete) makes the link 404 publicly.
//
// Real: admin + public partner routers, requireHouse, requireRoles, models,
// in-memory Mongo. Stubbed: the caller (from a header) and the workspace it
// resolved to.
import { describe, it, expect, beforeAll, afterAll, beforeEach } from "vitest";
import express from "express";
import request from "supertest";
import mongoose from "mongoose";
import { MongoMemoryServer } from "mongodb-memory-server";

process.env.NODE_ENV = "test";

const { default: adminRouter } = await import("./admin.partnerLinks.js");
const { default: publicRouter } = await import("./public.partnerRequest.js");
const { requireHouse } = await import("../middleware/requireHouse.js");
const { partnerLinkResolveLimiter } = await import("../middleware/rateLimit.js");

const HOUSE = "69679a7628330a58d29f2254";
const oid = () => new mongoose.Types.ObjectId();
const AMBER = oid();
const AMBER_CUSTOMER = oid();
const DORMANT = oid();

const app = express();
app.use(express.json());
app.use(
  "/api/admin/partner-links",
  (req: any, _res, next) => {
    req.user = JSON.parse(String(req.headers["x-test-user"] || "{}"));
    req.workspaceId = String(req.headers["x-test-ws"] || "");
    next();
  },
  requireHouse,
  adminRouter,
);
app.use("/api/public", publicRouter);

const ADMIN = { sub: String(oid()), email: "ops-admin@plumtrips.com", roles: ["ADMIN"] };
const SA = { sub: String(oid()), email: "sa@plumtrips.com", roles: ["SUPERADMIN"] };
const STAFF = { sub: String(oid()), email: "staff@plumtrips.com", roles: ["EMPLOYEE"] };
const TENANT_ADMIN = { sub: String(oid()), email: "admin@amber.test", roles: ["ADMIN"] };

const call = (method: "get" | "post" | "patch" | "delete", path: string, who: any, ws = HOUSE) =>
  (request(app) as any)[method](`/api/admin/partner-links${path}`).set("x-test-user", JSON.stringify(who)).set("x-test-ws", ws);

let mongod: MongoMemoryServer;
const col = (n: string) => mongoose.connection.db!.collection(n);

beforeAll(async () => {
  mongod = await MongoMemoryServer.create();
  await mongoose.connect(mongod.getUri("admin-partner-links-test"));
}, 120_000);
afterAll(async () => {
  await mongoose.disconnect();
  await mongod?.stop();
});
beforeEach(async () => {
  await mongoose.connection.db!.dropDatabase();
  for (const key of ["::ffff:127.0.0.1", "127.0.0.1", "::1"]) await (partnerLinkResolveLimiter as any).resetKey?.(key);
  await col("customerworkspaces").insertMany([
    { _id: AMBER, customerId: String(AMBER_CUSTOMER), companyName: "Amber Student", status: "ACTIVE" },
    { _id: DORMANT, customerId: String(oid()), companyName: "Dormant Co", status: "SUSPENDED" },
  ] as any[]);
});

const create = (over: any = {}, who: any = ADMIN) =>
  call("post", "", who).send({ workspaceId: String(AMBER), label: "Amber — homepage banner", placement: "homepage-banner", ...over });

describe("who may manage partner links", () => {
  it("HOUSE ADMIN and SUPERADMIN only", async () => {
    expect((await create({}, ADMIN)).status).toBe(201);
    expect((await create({}, SA)).status).toBe(201);
    expect((await create({}, STAFF)).status).toBe(403);
    expect((await call("get", "", STAFF)).status).toBe(403);
    // A tenant's own admin, in their own workspace: refused by requireHouse.
    expect((await call("post", "", TENANT_ADMIN, String(AMBER)).send({ workspaceId: String(AMBER), label: "x" })).status).toBe(403);
    expect(await col("partnerlinks").countDocuments({})).toBe(2);
  });
});

describe("create", () => {
  it("the server picks the code and copies the customerId; a body code / customerId / counter is ignored", async () => {
    const res = await create({ code: "CHOSEN01", customerId: String(oid()), clicks: 999, active: false, services: ["flight", "visa"], allowedOrigins: ["https://amberstudent.com"], dailyCap: 50, utmDefaults: { utm_source: "amber" } });
    expect(res.status, JSON.stringify(res.body)).toBe(201);
    const link = res.body.link;
    expect(link.code).toMatch(/^[0-9A-Za-z]{8}$/);
    expect(link.code).not.toBe("CHOSEN01");
    expect(link).toMatchObject({ partnerName: "Amber Student", active: true, clicks: 0, services: ["flight", "visa"], allowedOrigins: ["https://amberstudent.com"], dailyCap: 50 });
    const stored: any = await col("partnerlinks").findOne({ code: link.code });
    expect(stored.customerId).toBe(String(AMBER_CUSTOMER));
    expect(stored.utmDefaults.source).toBe("amber");
  });

  it("refuses bad input and an inactive or unknown workspace", async () => {
    expect((await create({ label: "" })).status).toBe(400);
    expect((await create({ services: ["cab"] })).status).toBe(400);
    expect((await create({ services: [] })).status).toBe(400);
    expect((await create({ allowedOrigins: ["http://amberstudent.com"] })).status).toBe(400);
    expect((await create({ allowedOrigins: ["https://amberstudent.com/path"] })).status).toBe(400);
    expect((await create({ allowedOrigins: ["https://*.amberstudent.com"] })).status).toBe(400);
    expect((await create({ dailyCap: 0 })).status).toBe(400);
    expect((await create({ workspaceId: String(DORMANT) })).status).toBe(400);
    expect((await create({ workspaceId: String(oid()) })).status).toBe(400);
    expect(await col("partnerlinks").countDocuments({})).toBe(0);
  });

  it("defaults: flight, hotel and visa; cap 200; not embeddable", async () => {
    const { link } = (await create()).body;
    expect(link).toMatchObject({ services: ["flight", "hotel", "visa"], dailyCap: 200, embedAllowed: false, allowedOrigins: [] });
  });
});

describe("partner picker", () => {
  it("active workspaces by name, never HOUSE; short queries return nothing", async () => {
    await col("customerworkspaces").insertOne({ _id: new mongoose.Types.ObjectId(HOUSE), customerId: "HOUSE", companyName: "Amber House (Plumtrips)", status: "ACTIVE" } as any);
    const r = await call("get", "/partners?q=amb", ADMIN);
    expect(r.status).toBe(200);
    expect(r.body.partners).toEqual([{ workspaceId: String(AMBER), name: "Amber Student" }]);
    expect((await call("get", "/partners?q=dorm", ADMIN)).body.partners).toEqual([]); // suspended
    expect((await call("get", "/partners?q=a", ADMIN)).body.partners).toEqual([]);
    expect((await call("get", "/partners?q=(", ADMIN)).status).toBe(200); // regex characters are literal
    expect((await call("get", "/partners?q=amb", STAFF)).status).toBe(403);
  });
});

describe("list, edit, deactivate", () => {
  it("lists by workspace; edits the editable fields only", async () => {
    const { link } = (await create()).body;
    const list = await call("get", `?workspaceId=${AMBER}`, ADMIN);
    expect(list.body.links.map((l: any) => l.code)).toEqual([link.code]);
    expect((await call("get", `?workspaceId=${oid()}`, ADMIN)).body.links).toEqual([]);

    const edited = await call("patch", `/${link.id}`, ADMIN).send({ label: "Amber — checkout", services: ["hotel"], code: "NEWCODE1", workspaceId: String(oid()), active: false });
    expect(edited.status).toBe(200);
    expect(edited.body.link).toMatchObject({ code: link.code, label: "Amber — checkout", services: ["hotel"], active: true, workspaceId: String(AMBER) });
    expect((await call("patch", `/${link.id}`, ADMIN).send({ code: "X" })).status).toBe(400); // nothing editable
  });

  it("deactivate stops the public link; there is no delete", async () => {
    const { link } = (await create()).body;
    expect((await request(app).get(`/api/public/partner-links/${link.code}`)).status).toBe(200);
    const off = await call("post", `/${link.id}/deactivate`, ADMIN);
    expect(off.status).toBe(200);
    expect(off.body.link.active).toBe(false);
    expect((await call("post", `/${link.id}/deactivate`, ADMIN)).status).toBe(400);
    expect((await request(app).get(`/api/public/partner-links/${link.code}`)).status).toBe(404);
    expect((await call("delete", `/${link.id}`, ADMIN)).status).toBe(404);
    expect(await col("partnerlinks").countDocuments({})).toBe(1);
    const stored: any = await col("partnerlinks").findOne({});
    expect(stored.deactivatedBy).toBe(ADMIN.email);
  });
});
